import { useState } from 'react';
import { usePanelData } from '../hooks/usePanelData';
import { api } from '../lib/api';
import type { EquityReport } from '../types';
import type { ExecutiveBriefResponse } from '../types';
import { PanelSkeleton } from './PanelStates';
import ExecutiveBriefView from './ExecutiveBriefView';

/**
 * Councillor brief: the strongest findings with the economics a council
 * audience needs — rider estimates, annualized rider-minutes, fix kind and
 * cost, plus a realtime-validated lateness summary and every source.
 *
 * Ward data is shown ONLY as the *delay location* (where the wait happens) —
 * riders waiting at a stop are often from other wards, so the panel never
 * attributes riders to the ward of the stop.
 *
 * P3 split: this file is the DATA SHELL only — usePanelData wiring plus the
 * skeleton/error gates. The full render (header, crowding, ghosts, seams,
 * transfers, economics, sources, equity fold) lives in
 * `ExecutiveBriefView.tsx` as a prop-only component.
 */
export default function ExecutiveBriefPanel({
  serviceDay,
  onNavigate,
}: {
  serviceDay: string;
  /** Navigate to a view, optionally highlighting a route. */
  onNavigate: (view: string, route?: string) => void;
}) {
  // P2: fetch/loading/error owned by the hook, keyed on serviceDay (was a
  // hand-rolled trio + effect). The equity fold (T158 rule 3) stays a
  // best-effort side fetch INSIDE the primary fetcher — its failure only
  // omits the fold, never the brief. Guarded against a missing method (test
  // mocks / older API builds), same discipline as useDataVintages.
  const [equity, setEquity] = useState<EquityReport | null>(null);
  const { data, error, loading } = usePanelData<ExecutiveBriefResponse>({
    fetcher: () => {
      const eq = api.equityReport as (() => Promise<EquityReport>) | undefined;
      let eqPromise: Promise<void> | null = null;
      if (typeof eq === 'function') {
        // A bare test-mock vi.fn() RETURNS UNDEFINED — guard the result,
        // not just the method (useDataVintages guards only the method because
        // its mocks always resolve; here the side-chain is built eagerly).
        const ret = eq.call(api) as Promise<EquityReport> | undefined;
        if (ret != null && typeof ret.then === 'function') {
          eqPromise = ret.then(setEquity).catch(() => setEquity(null));
        }
      }
      void eqPromise;
      return api.executiveBrief({ service_day: serviceDay });
    },
    deps: [serviceDay],
  });

  if (loading && !data) {
    return <PanelSkeleton label="Building the brief…" />;
  }

  if (error) {
    return (
      <div
        role="alert"
        className="rounded-xl border border-danger/40 bg-danger/10 p-6 text-sm text-danger"
      >
        Could not load the executive brief: {error}
      </div>
    );
  }
  if (!data) return null;

  return <ExecutiveBriefView data={data} equity={equity} onNavigate={onNavigate} />;
}
